// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/**
 * @title MinimalForwarderSecure
 * @dev Security-enhanced minimal forwarder to be used together with an ERC2771 compatible contract.
 * This implementation includes enhanced security measures for TrataTech gasless transactions.
 */
contract MinimalForwarderSecure is EIP712 {
    using ECDSA for bytes32;

    // ============ CONSTANTS ============

    // SECURITY: Gas validation constants to prevent various gas-related attacks
    uint256 public constant MIN_GAS_LIMIT = 21000; // Minimum gas for a transaction
    uint256 public constant MAX_GAS_LIMIT = 10000000; // Maximum gas to prevent DoS
    uint256 public constant GAS_BUFFER_RATIO = 64; // Conservative gas buffer (was 63)
    uint256 public constant MAX_DATA_SIZE = 100000; // Maximum data size to prevent spam
    uint256 public constant MAX_VALUE = 1000 ether; // Maximum value to prevent large value attacks

    // ============ CUSTOM ERRORS ============

    error InvalidSignature();
    error NonceAlreadyUsed(address user, uint256 nonce);
    error InvalidGasLimit(uint256 provided, uint256 min, uint256 max);
    error InsufficientGasProvided(uint256 gasLeft, uint256 required);
    error InvalidDataSize(uint256 size, uint256 max);
    error InvalidValue(uint256 value, uint256 max);
    error InvalidAddress(string parameter);
    error ExecutionFailed();
    error ReentrancyDetected();

    // ============ STRUCTS ============

    struct ForwardRequest {
        address from;
        address to;
        uint256 value;
        uint256 gas;
        uint256 nonce;
        bytes data;
    }

    // ============ STATE VARIABLES ============

    bytes32 private constant _TYPEHASH =
        keccak256("ForwardRequest(address from,address to,uint256 value,uint256 gas,uint256 nonce,bytes data)");

    mapping(address => uint256) private _nonces;

    // SECURITY: Reentrancy protection
    bool private _executing;

    // SECURITY: Track failed executions to prevent spam
    mapping(address => uint256) private _failedExecutions;
    uint256 public constant MAX_FAILED_EXECUTIONS = 10;

    // ============ EVENTS ============

    event MetaTransactionExecuted(
        address indexed from,
        address indexed to,
        bytes indexed dataHash,
        bool success,
        uint256 gasUsed
    );

    event InvalidExecution(
        address indexed from,
        address indexed to,
        string reason
    );

    // ============ CONSTRUCTOR ============

    constructor() EIP712("MinimalForwarderSecure", "2.0.0") {}

    // ============ VIEW FUNCTIONS ============

    function getNonce(address from) public view returns (uint256) {
        if (from == address(0)) {
            revert InvalidAddress("from");
        }
        return _nonces[from];
    }

    function getFailedExecutions(address from) public view returns (uint256) {
        return _failedExecutions[from];
    }

    // ============ VERIFICATION FUNCTIONS ============

    function verify(ForwardRequest calldata req, bytes calldata signature) public view returns (bool) {
        // SECURITY: Enhanced input validation
        if (req.from == address(0)) {
            return false;
        }
        if (req.to == address(0)) {
            return false;
        }
        if (req.gas < MIN_GAS_LIMIT || req.gas > MAX_GAS_LIMIT) {
            return false;
        }
        if (req.data.length > MAX_DATA_SIZE) {
            return false;
        }
        if (req.value > MAX_VALUE) {
            return false;
        }
        if (signature.length == 0) {
            return false;
        }

        // SECURITY: Check nonce hasn't been used
        if (_nonces[req.from] != req.nonce) {
            return false;
        }

        // SECURITY: Verify signature
        bytes32 digest = _hashTypedDataV4(
            keccak256(abi.encode(_TYPEHASH, req.from, req.to, req.value, req.gas, req.nonce, keccak256(req.data)))
        );

        address signer = digest.recover(signature);
        return signer == req.from;
    }

    // ============ EXECUTION FUNCTIONS ============

    function execute(ForwardRequest calldata req, bytes calldata signature)
        public
        payable
        returns (bool, bytes memory)
    {
        // SECURITY: Reentrancy protection
        if (_executing) {
            revert ReentrancyDetected();
        }
        _executing = true;

        // SECURITY: Enhanced input validation
        _validateRequest(req);

        // SECURITY: Check failed execution limit
        if (_failedExecutions[req.from] >= MAX_FAILED_EXECUTIONS) {
            emit InvalidExecution(req.from, req.to, "Too many failed executions");
            _executing = false;
            revert ExecutionFailed();
        }

        // SECURITY: Verify signature
        if (!verify(req, signature)) {
            _failedExecutions[req.from]++;
            emit InvalidExecution(req.from, req.to, "Invalid signature");
            _executing = false;
            revert InvalidSignature();
        }

        // SECURITY: Update nonce before external call
        _nonces[req.from] = req.nonce + 1;

        // SECURITY: More conservative gas checking before execution
        uint256 gasBeforeExecution = gasleft();
        if (gasBeforeExecution < req.gas + (req.gas / GAS_BUFFER_RATIO)) {
            _failedExecutions[req.from]++;
            emit InvalidExecution(req.from, req.to, "Insufficient gas provided");
            _executing = false;
            revert InsufficientGasProvided(gasBeforeExecution, req.gas + (req.gas / GAS_BUFFER_RATIO));
        }

        // Execute the call with enhanced security
        (bool success, bytes memory returndata) = _executeCall(req);

        // SECURITY: Enhanced gas validation after execution
        uint256 gasAfterExecution = gasleft();
        uint256 gasUsed = gasBeforeExecution - gasAfterExecution;

        if (gasAfterExecution <= req.gas / GAS_BUFFER_RATIO) {
            // SECURITY: More conservative gas validation
            /// @solidity memory-safe-assembly
            assembly {
                invalid()
            }
        }

        // SECURITY: Track failed executions
        if (!success) {
            _failedExecutions[req.from]++;
        } else {
            // Reset counter on successful execution
            _failedExecutions[req.from] = 0;
        }

        emit MetaTransactionExecuted(req.from, req.to, abi.encodePacked(keccak256(req.data)), success, gasUsed);

        _executing = false;
        return (success, returndata);
    }

    // ============ INTERNAL FUNCTIONS ============

    function _validateRequest(ForwardRequest calldata req) private pure {
        if (req.from == address(0)) {
            revert InvalidAddress("from");
        }
        if (req.to == address(0)) {
            revert InvalidAddress("to");
        }
        if (req.gas < MIN_GAS_LIMIT || req.gas > MAX_GAS_LIMIT) {
            revert InvalidGasLimit(req.gas, MIN_GAS_LIMIT, MAX_GAS_LIMIT);
        }
        if (req.data.length > MAX_DATA_SIZE) {
            revert InvalidDataSize(req.data.length, MAX_DATA_SIZE);
        }
        if (req.value > MAX_VALUE) {
            revert InvalidValue(req.value, MAX_VALUE);
        }
    }

    function _executeCall(ForwardRequest calldata req) private returns (bool success, bytes memory returndata) {
        // SECURITY: Use call with explicit gas limit and value
        (success, returndata) = req.to.call{
            gas: req.gas,
            value: req.value
        }(abi.encodePacked(req.data, req.from));

        return (success, returndata);
    }

    // ============ BATCH EXECUTION ============

    function executeBatch(
        ForwardRequest[] calldata requests,
        bytes[] calldata signatures
    ) external payable returns (bool[] memory successes, bytes[] memory returndatas) {
        // SECURITY: Limit batch size to prevent DoS
        if (requests.length > 10) {
            revert InvalidValue(requests.length, 10);
        }
        if (requests.length != signatures.length) {
            revert InvalidValue(signatures.length, requests.length);
        }

        successes = new bool[](requests.length);
        returndatas = new bytes[](requests.length);

        for (uint256 i = 0; i < requests.length; i++) {
            try this.execute(requests[i], signatures[i]) returns (bool success, bytes memory returndata) {
                successes[i] = success;
                returndatas[i] = returndata;
            } catch {
                successes[i] = false;
                returndatas[i] = "";
            }
        }

        return (successes, returndatas);
    }

    // ============ ADMIN FUNCTIONS ============

    function resetFailedExecutions(address user) external {
        // SECURITY: Only allow users to reset their own counter or implement proper access control
        require(msg.sender == user, "Can only reset own failed executions");
        _failedExecutions[user] = 0;
    }

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "2.0.0-secure";
    }
}

contracts/fixcontract/TrataTechMainUpgra.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechMainUpgradeableSecure
 * @dev Security-enhanced upgradeable and gasless version of TrataTech platform handling:
 * - Event Invites & RSVP
 * - Product Launches & Early Access
 * - Digital Product Passports
 * - Digital Art Drops
 * - Offers & Coupons
 * @author Advanced Developer
 */
contract TrataTechMainUpgradeableSecure is
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    ERC2771ContextUpgradeable
{
    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ CONSTANTS ============

    // SECURITY: All constants before storage variables to prevent layout collision
    uint256 public constant MAX_AIRDROP_RECIPIENTS = 50;
    uint256 public constant MAX_STRING_LENGTH = 1000;
    uint256 public constant MAX_DESCRIPTION_LENGTH = 5000;
    uint256 public constant MAX_IPFS_CID_LENGTH = 100;
    uint256 public constant MAX_ATTENDEES_LIMIT = 10000;
    uint256 public constant MAX_EARLY_ACCESS_LIMIT = 1000;
    uint256 public constant MAX_EDITIONS_LIMIT = 100000;
    uint256 public constant MAX_DISCOUNT_PERCENTAGE = 10000; // 100%
    uint256 public constant MIN_EVENT_LEAD_TIME = 1 hours; // Minimum time between creation and event
    uint256 public constant MAX_FUTURE_DATE = 365 days * 10; // 10 years max
    uint256 public constant MIN_DISCOUNT_PERCENTAGE = 100; // 1%
    uint256 public constant MAX_REDEMPTIONS_LIMIT = 1000000;

    // ============ CUSTOM ERRORS ============

    error InvalidAddress(string parameter);
    error InvalidLength(string parameter, uint256 current, uint256 max);
    error InvalidDateRange(string parameter, uint256 provided, uint256 minimum);
    error InvalidValue(string parameter, uint256 current, uint256 expected);
    error InvalidRange(string parameter, uint256 current, uint256 min, uint256 max);
    error CounterOverflow(string counter);
    error AlreadyExists(string item);
    error DoesNotExist(string item);
    error NotAuthorized(string role);
    error LimitExceeded(string limit, uint256 current, uint256 max);
    error OperationNotAllowed(string reason);
    error ContractPaused();
    error EmergencyStopActive();
    error InvalidProof();
    error AlreadyRedeemed();
    error ExpiredOffer();
    error InvalidState(string expected, string current);

    // ============ STRUCTS ============

    struct EventInvite {
        uint256 eventId;
        string eventName;
        string eventDescription;
        uint256 eventDate;
        uint256 maxAttendees;
        uint256 currentAttendees;
        string ipfsCID;
        bool isActive;
        bool isCancelled;
        mapping(address => bool) attendees;
        mapping(address => uint256) attendeeTokens;
    }

    struct ProductLaunch {
        uint256 launchId;
        string productName;
        string productDescription;
        uint256 launchDate;
        uint256 earlyAccessEndDate;
        string ipfsCID;
        bool isActive;
        bool isLaunched;
        uint256 maxEarlyAccess;
        uint256 currentEarlyAccess;
        mapping(address => bool) earlyAccessUsers;
        mapping(address => bool) preOrders;
    }

    struct DigitalProductPassport {
        uint256 dppId;
        string productId;
        string brandId;
        string ipfsCID;
        uint256 timestamp;
        bool isValid;
        address creator;
        string metadataHash;
    }

    struct DigitalArtDrop {
        uint256 dropId;
        string artistName;
        string artworkTitle;
        uint256 edition;
        uint256 maxEditions;
        string ipfsCID;
        bool isActive;
        bool isLimited;
        uint256 currentAirdrops;
        mapping(address => bool) airdroppedTo;
    }

    struct Offer {
        uint256 offerId;
        string title;
        uint256 discountPercentage;
        uint256 validFrom;
        uint256 validUntil;
        string productScope;
        string conditions;
        string ipfsCID;
        bool isActive;
        bool isMerkleBased;
        bytes32 merkleRoot;
        uint256 maxRedemptions;
        uint256 currentRedemptions;
        mapping(address => bool) redeemedBy;
        mapping(address => uint256) userRedemptions;
    }

    enum TokenType {
        EVENT_INVITE,
        PRODUCT_LAUNCH,
        DIGITAL_ART,
        OFFER_COUPON,
        DPP_PASSPORT
    }

    // ============ STATE VARIABLES ============

    uint256 private _tokenIds;
    uint256 private _eventIds;
    uint256 private _launchIds;
    uint256 private _dppIds;
    uint256 private _dropIds;
    uint256 private _offerIds;

    // Mappings
    mapping(uint256 => EventInvite) private _events;
    mapping(uint256 => ProductLaunch) private _launches;
    mapping(uint256 => DigitalProductPassport) private _dpps;
    mapping(uint256 => DigitalArtDrop) private _drops;
    mapping(uint256 => Offer) private _offers;

    // Token type mapping
    mapping(uint256 => TokenType) private _tokenTypes;
    mapping(uint256 => uint256) private _tokenReferences;

    // Access control
    mapping(address => bool) private _authorizedBrands;
    mapping(address => bool) private _authorizedOperators;

    // Emergency controls
    bool private _emergencyStop;

    // SECURITY: Storage gap for future upgrades
    uint256[40] private __gap;

    // ============ EVENTS ============

    event EventCreated(uint256 indexed eventId, string eventName, uint256 eventDate, string ipfsCID);
    event EventCancelled(uint256 indexed eventId);
    event RSVPSubmitted(uint256 indexed eventId, address indexed attendee, uint256 tokenId);
    event RSVPCancelled(uint256 indexed eventId, address indexed attendee);

    event ProductLaunchCreated(uint256 indexed launchId, string productName, uint256 launchDate, string ipfsCID);
    event EarlyAccessGranted(uint256 indexed launchId, address indexed user, uint256 tokenId);
    event PreOrderPlaced(uint256 indexed launchId, address indexed user, uint256 amount);

    event DPPCreated(uint256 indexed dppId, string productId, string brandId, string ipfsCID);
    event DPPInvalidated(uint256 indexed dppId);

    event ArtDropCreated(uint256 indexed dropId, string artistName, string artworkTitle, string ipfsCID);
    event ArtAirdropped(uint256 indexed dropId, address indexed recipient, uint256 tokenId);

    event OfferCreated(uint256 indexed offerId, string title, uint256 discountPercentage, string ipfsCID);
    event OfferRedeemed(uint256 indexed offerId, address indexed user);
    event OfferExpired(uint256 indexed offerId);

    event BrandAuthorized(address indexed brand);
    event BrandRevoked(address indexed brand);
    event OperatorAuthorized(address indexed operator);
    event OperatorRevoked(address indexed operator);
    event EmergencyStopActivated();
    event EmergencyStopDeactivated();

    // ============ MODIFIERS ============

    modifier onlyAuthorizedBrand() {
        if (!_authorizedBrands[_msgSender()] && _msgSender() != owner()) {
            revert NotAuthorized("authorized brand");
        }
        _;
    }

    modifier onlyAuthorizedOperator() {
        if (!_authorizedOperators[_msgSender()] && _msgSender() != owner()) {
            revert NotAuthorized("authorized operator");
        }
        _;
    }

    modifier notEmergencyStopped() {
        if (_emergencyStop) {
            revert EmergencyStopActive();
        }
        _;
    }

    modifier validEvent(uint256 eventId) {
        if (_events[eventId].eventId == 0) {
            revert DoesNotExist("event");
        }
        if (!_events[eventId].isActive) {
            revert InvalidState("active", "inactive");
        }
        if (_events[eventId].isCancelled) {
            revert InvalidState("not cancelled", "cancelled");
        }
        _;
    }

    modifier validLaunch(uint256 launchId) {
        if (_launches[launchId].launchId == 0) {
            revert DoesNotExist("launch");
        }
        if (!_launches[launchId].isActive) {
            revert InvalidState("active", "inactive");
        }
        _;
    }

    modifier validOffer(uint256 offerId) {
        if (_offers[offerId].offerId == 0) {
            revert DoesNotExist("offer");
        }
        if (!_offers[offerId].isActive) {
            revert InvalidState("active", "inactive");
        }
        // SECURITY: Enhanced timestamp validation with tolerance
        if (block.timestamp + 300 < _offers[offerId].validFrom) { // 5 min tolerance
            revert InvalidDateRange("offer start", _offers[offerId].validFrom, block.timestamp);
        }
        if (block.timestamp > _offers[offerId].validUntil + 300) { // 5 min tolerance
            revert ExpiredOffer();
        }
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        if (trustedForwarder == address(0)) {
            revert InvalidAddress("trustedForwarder");
        }
        _disableInitializers();
    }

    function initialize(address initialOwner, address trustedForwarder) public initializer {
        // SECURITY: Enhanced input validation
        if (initialOwner == address(0)) {
            revert InvalidAddress("initialOwner");
        }
        if (trustedForwarder == address(0)) {
            revert InvalidAddress("trustedForwarder");
        }

        __ERC721_init("TrataTech Platform", "TRATA");
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        // SECURITY: Counter overflow protection
        _tokenIds = 1;
    }

    // ============ UUPS UPGRADE AUTHORIZATION ============

    function _authorizeUpgrade(address newImplementation) internal view override onlyOwner {
        // SECURITY: Additional validation for upgrades
        if (newImplementation == address(0)) {
            revert InvalidAddress("newImplementation");
        }
    }

    // ============ ERC2771 OVERRIDES FOR GASLESS ============

    function _msgSender() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ INPUT VALIDATION HELPERS ============

    function _validateStringLength(string memory str, string memory paramName, uint256 maxLength) private pure {
        if (bytes(str).length == 0 || bytes(str).length > maxLength) {
            revert InvalidLength(paramName, bytes(str).length, maxLength);
        }
    }

    function _validateAddress(address addr, string memory paramName) private pure {
        if (addr == address(0)) {
            revert InvalidAddress(paramName);
        }
    }

    function _validateDateRange(uint256 date, uint256 minDate, string memory paramName) private view {
        if (date < minDate) {
            revert InvalidDateRange(paramName, date, minDate);
        }
        if (date > block.timestamp + MAX_FUTURE_DATE) {
            revert InvalidDateRange(paramName, date, block.timestamp + MAX_FUTURE_DATE);
        }
    }

    function _validateRange(uint256 value, uint256 min, uint256 max, string memory paramName) private pure {
        if (value < min || value > max) {
            revert InvalidRange(paramName, value, min, max);
        }
    }

    // ============ GETTER FUNCTIONS ============

    function events(uint256 eventId) external view returns (
        uint256 eventId_,
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        uint256 currentAttendees,
        string memory ipfsCID,
        bool isActive,
        bool isCancelled
    ) {
        EventInvite storage eventData = _events[eventId];
        return (
            eventData.eventId,
            eventData.eventName,
            eventData.eventDescription,
            eventData.eventDate,
            eventData.maxAttendees,
            eventData.currentAttendees,
            eventData.ipfsCID,
            eventData.isActive,
            eventData.isCancelled
        );
    }

    function launches(uint256 launchId) external view returns (
        uint256 launchId_,
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        string memory ipfsCID,
        bool isActive,
        bool isLaunched,
        uint256 maxEarlyAccess,
        uint256 currentEarlyAccess
    ) {
        ProductLaunch storage launch = _launches[launchId];
        return (
            launch.launchId,
            launch.productName,
            launch.productDescription,
            launch.launchDate,
            launch.earlyAccessEndDate,
            launch.ipfsCID,
            launch.isActive,
            launch.isLaunched,
            launch.maxEarlyAccess,
            launch.currentEarlyAccess
        );
    }

    function offers(uint256 offerId) external view returns (
        uint256 offerId_,
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isActive,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions,
        uint256 currentRedemptions
    ) {
        Offer storage offer = _offers[offerId];
        return (
            offer.offerId,
            offer.title,
            offer.discountPercentage,
            offer.validFrom,
            offer.validUntil,
            offer.productScope,
            offer.conditions,
            offer.ipfsCID,
            offer.isActive,
            offer.isMerkleBased,
            offer.merkleRoot,
            offer.maxRedemptions,
            offer.currentRedemptions
        );
    }

    function tokenTypes(uint256 tokenId) external view returns (TokenType) {
        return _tokenTypes[tokenId];
    }

    function tokenReferences(uint256 tokenId) external view returns (uint256) {
        return _tokenReferences[tokenId];
    }

    function authorizedBrands(address brand) external view returns (bool) {
        return _authorizedBrands[brand];
    }

    function authorizedOperators(address operator) external view returns (bool) {
        return _authorizedOperators[operator];
    }

    function emergencyStop() external view returns (bool) {
        return _emergencyStop;
    }

    // ============ EVENT MANAGEMENT ============

    function createEventInvite(
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        // SECURITY: Enhanced input validation
        _validateStringLength(eventName, "eventName", MAX_STRING_LENGTH);
        _validateStringLength(eventDescription, "eventDescription", MAX_DESCRIPTION_LENGTH);
        _validateStringLength(ipfsCID, "ipfsCID", MAX_IPFS_CID_LENGTH);
        _validateDateRange(eventDate, block.timestamp + MIN_EVENT_LEAD_TIME, "eventDate");
        _validateRange(maxAttendees, 1, MAX_ATTENDEES_LIMIT, "maxAttendees");

        // SECURITY: Counter overflow protection
        if (_eventIds >= type(uint256).max - 1) {
            revert CounterOverflow("eventIds");
        }

        _eventIds = _eventIds + 1;
        uint256 eventId = _eventIds;

        EventInvite storage newEvent = _events[eventId];
        newEvent.eventId = eventId;
        newEvent.eventName = eventName;
        newEvent.eventDescription = eventDescription;
        newEvent.eventDate = eventDate;
        newEvent.maxAttendees = maxAttendees;
        newEvent.currentAttendees = 0;
        newEvent.ipfsCID = ipfsCID;
        newEvent.isActive = true;
        newEvent.isCancelled = false;

        emit EventCreated(eventId, eventName, eventDate, ipfsCID);
        return eventId;
    }

    function submitRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        if (eventData.attendees[_msgSender()]) {
            revert AlreadyExists("RSVP");
        }
        if (eventData.currentAttendees >= eventData.maxAttendees) {
            revert LimitExceeded("event capacity", eventData.currentAttendees, eventData.maxAttendees);
        }
        // SECURITY: Enhanced timestamp validation with tolerance
        if (block.timestamp + MIN_EVENT_LEAD_TIME > eventData.eventDate) {
            revert OperationNotAllowed("event has already started or starting soon");
        }

        // SECURITY: Counter overflow protection
        if (_tokenIds >= type(uint256).max - 1) {
            revert CounterOverflow("tokenIds");
        }

        // SECURITY: Complete state changes before external calls
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        eventData.attendees[_msgSender()] = true;
        eventData.attendeeTokens[_msgSender()] = tokenId;
        eventData.currentAttendees = eventData.currentAttendees + 1;

        _tokenTypes[tokenId] = TokenType.EVENT_INVITE;
        _tokenReferences[tokenId] = eventId;

        // SECURITY: External call last
        _safeMint(_msgSender(), tokenId);

        emit RSVPSubmitted(eventId, _msgSender(), tokenId);
    }

    function cancelRSVP(uint256 eventId) external validEvent(eventId) notEmergencyStopped nonReentrant {
        EventInvite storage eventData = _events[eventId];

        if (!eventData.attendees[_msgSender()]) {
            revert DoesNotExist("RSVP");
        }
        // SECURITY: Enhanced timestamp validation
        if (block.timestamp + MIN_EVENT_LEAD_TIME > eventData.eventDate) {
            revert OperationNotAllowed("event has already started or starting soon");
        }

        uint256 tokenId = eventData.attendeeTokens[_msgSender()];

        // SECURITY: Complete state changes before external calls
        eventData.attendees[_msgSender()] = false;
        eventData.attendeeTokens[_msgSender()] = 0;
        eventData.currentAttendees = eventData.currentAttendees - 1;

        // SECURITY: External call last
        _burn(tokenId);

        emit RSVPCancelled(eventId, _msgSender());
    }

    function cancelEvent(uint256 eventId) external {
        if (_events[eventId].eventId == 0) {
            revert DoesNotExist("event");
        }
        if (_msgSender() != owner() && !_authorizedBrands[_msgSender()]) {
            revert NotAuthorized("owner or authorized brand");
        }

        _events[eventId].isCancelled = true;
        _events[eventId].isActive = false;

        emit EventCancelled(eventId);
    }

    // ============ PRODUCT LAUNCH MANAGEMENT ============

    function createProductLaunch(
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        uint256 maxEarlyAccess,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        // SECURITY: Enhanced input validation
        _validateStringLength(productName, "productName", MAX_STRING_LENGTH);
        _validateStringLength(productDescription, "productDescription", MAX_DESCRIPTION_LENGTH);
        _validateStringLength(ipfsCID, "ipfsCID", MAX_IPFS_CID_LENGTH);
        _validateDateRange(launchDate, block.timestamp + MIN_EVENT_LEAD_TIME, "launchDate");
        _validateRange(maxEarlyAccess, 1, MAX_EARLY_ACCESS_LIMIT, "maxEarlyAccess");

        if (earlyAccessEndDate < block.timestamp + MIN_EVENT_LEAD_TIME || earlyAccessEndDate > launchDate) {
            revert InvalidDateRange("earlyAccessEndDate", earlyAccessEndDate, block.timestamp + MIN_EVENT_LEAD_TIME);
        }

        // SECURITY: Counter overflow protection
        if (_launchIds >= type(uint256).max - 1) {
            revert CounterOverflow("launchIds");
        }

        _launchIds = _launchIds + 1;
        uint256 launchId = _launchIds;

        ProductLaunch storage newLaunch = _launches[launchId];
        newLaunch.launchId = launchId;
        newLaunch.productName = productName;
        newLaunch.productDescription = productDescription;
        newLaunch.launchDate = launchDate;
        newLaunch.earlyAccessEndDate = earlyAccessEndDate;
        newLaunch.ipfsCID = ipfsCID;
        newLaunch.isActive = true;
        newLaunch.isLaunched = false;
        newLaunch.maxEarlyAccess = maxEarlyAccess;
        newLaunch.currentEarlyAccess = 0;

        emit ProductLaunchCreated(launchId, productName, launchDate, ipfsCID);
        return launchId;
    }

    function grantEarlyAccess(uint256 launchId, address user) external validLaunch(launchId) notEmergencyStopped nonReentrant {
        _validateAddress(user, "user");

        ProductLaunch storage launch = _launches[launchId];

        // SECURITY: Enhanced timestamp validation
        if (block.timestamp >= launch.earlyAccessEndDate) {
            revert OperationNotAllowed("early access period has ended");
        }
        if (launch.earlyAccessUsers[user]) {
            revert AlreadyExists("early access for user");
        }
        if (launch.currentEarlyAccess >= launch.maxEarlyAccess) {
            revert LimitExceeded("early access limit", launch.currentEarlyAccess, launch.maxEarlyAccess);
        }

        // SECURITY: Counter overflow protection
        if (_tokenIds >= type(uint256).max - 1) {
            revert CounterOverflow("tokenIds");
        }

        // SECURITY: Complete state changes before external calls
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        launch.earlyAccessUsers[user] = true;
        launch.currentEarlyAccess = launch.currentEarlyAccess + 1;

        _tokenTypes[tokenId] = TokenType.PRODUCT_LAUNCH;
        _tokenReferences[tokenId] = launchId;

        // SECURITY: External call last
        _safeMint(user, tokenId);

        emit EarlyAccessGranted(launchId, user, tokenId);
    }

    function placePreOrder(uint256 launchId) external validLaunch(launchId) notEmergencyStopped nonReentrant {
        ProductLaunch storage launch = _launches[launchId];

        // SECURITY: Enhanced timestamp validation
        if (block.timestamp >= launch.launchDate) {
            revert OperationNotAllowed("launch has already started");
        }
        if (launch.preOrders[_msgSender()]) {
            revert AlreadyExists("pre-order");
        }

        launch.preOrders[_msgSender()] = true;

        emit PreOrderPlaced(launchId, _msgSender(), 0);
    }

    // ============ DIGITAL PRODUCT PASSPORT MANAGEMENT ============

    function createDPP(
        string memory productId,
        string memory brandId,
        string memory ipfsCID,
        string memory metadataHash
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        // SECURITY: Enhanced input validation
        _validateStringLength(productId, "productId", MAX_STRING_LENGTH);
        _validateStringLength(brandId, "brandId", MAX_STRING_LENGTH);
        _validateStringLength(ipfsCID, "ipfsCID", MAX_IPFS_CID_LENGTH);
        _validateStringLength(metadataHash, "metadataHash", MAX_STRING_LENGTH);

        // SECURITY: Counter overflow protection
        if (_dppIds >= type(uint256).max - 1) {
            revert CounterOverflow("dppIds");
        }

        _dppIds = _dppIds + 1;
        uint256 dppId = _dppIds;

        DigitalProductPassport storage newDPP = _dpps[dppId];
        newDPP.dppId = dppId;
        newDPP.productId = productId;
        newDPP.brandId = brandId;
        newDPP.ipfsCID = ipfsCID;
        newDPP.timestamp = block.timestamp;
        newDPP.isValid = true;
        newDPP.creator = _msgSender();
        newDPP.metadataHash = metadataHash;

        emit DPPCreated(dppId, productId, brandId, ipfsCID);
        return dppId;
    }

    function invalidateDPP(uint256 dppId) external {
        if (_dpps[dppId].dppId == 0) {
            revert DoesNotExist("DPP");
        }
        if (_msgSender() != _dpps[dppId].creator && _msgSender() != owner()) {
            revert NotAuthorized("DPP creator or owner");
        }

        _dpps[dppId].isValid = false;

        emit DPPInvalidated(dppId);
    }

    // ============ DIGITAL ART DROP MANAGEMENT ============

    function createArtDrop(
        string memory artistName,
        string memory artworkTitle,
        uint256 edition,
        uint256 maxEditions,
        string memory ipfsCID
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        // SECURITY: Enhanced input validation
        _validateStringLength(artistName, "artistName", MAX_STRING_LENGTH);
        _validateStringLength(artworkTitle, "artworkTitle", MAX_STRING_LENGTH);
        _validateStringLength(ipfsCID, "ipfsCID", MAX_IPFS_CID_LENGTH);
        _validateRange(edition, 1, type(uint256).max, "edition");

        if (maxEditions > 0) {
            _validateRange(maxEditions, 1, MAX_EDITIONS_LIMIT, "maxEditions");
        }

        // SECURITY: Counter overflow protection
        if (_dropIds >= type(uint256).max - 1) {
            revert CounterOverflow("dropIds");
        }

        _dropIds = _dropIds + 1;
        uint256 dropId = _dropIds;

        DigitalArtDrop storage newDrop = _drops[dropId];
        newDrop.dropId = dropId;
        newDrop.artistName = artistName;
        newDrop.artworkTitle = artworkTitle;
        newDrop.edition = edition;
        newDrop.maxEditions = maxEditions;
        newDrop.ipfsCID = ipfsCID;
        newDrop.isActive = true;
        newDrop.isLimited = maxEditions > 0;
        newDrop.currentAirdrops = 0;

        emit ArtDropCreated(dropId, artistName, artworkTitle, ipfsCID);
        return dropId;
    }

    function airdropArtwork(uint256 dropId, address[] memory recipients) external onlyAuthorizedOperator notEmergencyStopped {
        // SECURITY: Enhanced input validation
        if (recipients.length == 0) {
            revert InvalidValue("recipients length", recipients.length, 1);
        }
        if (recipients.length > MAX_AIRDROP_RECIPIENTS) {
            revert LimitExceeded("batch size", recipients.length, MAX_AIRDROP_RECIPIENTS);
        }

        DigitalArtDrop storage drop = _drops[dropId];
        if (drop.dropId == 0) {
            revert DoesNotExist("drop");
        }
        if (!drop.isActive) {
            revert InvalidState("active", "inactive");
        }

        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            _validateAddress(recipient, "recipient");

            if (drop.airdroppedTo[recipient]) {
                revert AlreadyExists("airdrop for recipient");
            }

            if (drop.isLimited && drop.currentAirdrops >= drop.maxEditions) {
                revert LimitExceeded("max editions", drop.currentAirdrops, drop.maxEditions);
            }

            // SECURITY: Counter overflow protection
            if (_tokenIds >= type(uint256).max - 1) {
                revert CounterOverflow("tokenIds");
            }

            // SECURITY: Complete state changes before external calls
            _tokenIds = _tokenIds + 1;
            uint256 tokenId = _tokenIds;

            drop.airdroppedTo[recipient] = true;
            if (drop.isLimited) {
                drop.currentAirdrops++;
            }

            _tokenTypes[tokenId] = TokenType.DIGITAL_ART;
            _tokenReferences[tokenId] = dropId;

            // SECURITY: External call last
            _safeMint(recipient, tokenId);

            emit ArtAirdropped(dropId, recipient, tokenId);
        }
    }

    // ============ OFFER MANAGEMENT ============

    function createOffer(
        string memory title,
        uint256 discountPercentage,
        uint256 validFrom,
        uint256 validUntil,
        string memory productScope,
        string memory conditions,
        string memory ipfsCID,
        bool isMerkleBased,
        bytes32 merkleRoot,
        uint256 maxRedemptions
    ) external onlyAuthorizedBrand notEmergencyStopped returns (uint256) {
        // SECURITY: Enhanced input validation
        _validateStringLength(title, "title", MAX_STRING_LENGTH);
        _validateStringLength(productScope, "productScope", MAX_STRING_LENGTH);
        _validateStringLength(conditions, "conditions", MAX_DESCRIPTION_LENGTH);
        _validateStringLength(ipfsCID, "ipfsCID", MAX_IPFS_CID_LENGTH);
        _validateRange(discountPercentage, MIN_DISCOUNT_PERCENTAGE, MAX_DISCOUNT_PERCENTAGE, "discountPercentage");

        if (validFrom >= validUntil) {
            revert InvalidDateRange("validUntil", validUntil, validFrom + 1);
        }
        if (validUntil <= block.timestamp) {
            revert InvalidDateRange("validUntil", validUntil, block.timestamp + 1);
        }
        if (maxRedemptions > MAX_REDEMPTIONS_LIMIT) {
            revert InvalidRange("maxRedemptions", maxRedemptions, 0, MAX_REDEMPTIONS_LIMIT);
        }

        // SECURITY: Counter overflow protection
        if (_offerIds >= type(uint256).max - 1) {
            revert CounterOverflow("offerIds");
        }

        _offerIds = _offerIds + 1;
        uint256 offerId = _offerIds;

        Offer storage newOffer = _offers[offerId];
        newOffer.offerId = offerId;
        newOffer.title = title;
        newOffer.discountPercentage = discountPercentage;
        newOffer.validFrom = validFrom;
        newOffer.validUntil = validUntil;
        newOffer.productScope = productScope;
        newOffer.conditions = conditions;
        newOffer.ipfsCID = ipfsCID;
        newOffer.isActive = true;
        newOffer.isMerkleBased = isMerkleBased;
        newOffer.merkleRoot = merkleRoot;
        newOffer.maxRedemptions = maxRedemptions;
        newOffer.currentRedemptions = 0;

        emit OfferCreated(offerId, title, discountPercentage, ipfsCID);
        return offerId;
    }

    function redeemOffer(uint256 offerId, bytes32[] memory merkleProof) external validOffer(offerId) notEmergencyStopped nonReentrant {
        Offer storage offer = _offers[offerId];

        if (offer.redeemedBy[_msgSender()]) {
            revert AlreadyRedeemed();
        }

        if (offer.isMerkleBased) {
            bytes32 leaf = keccak256(abi.encodePacked(_msgSender()));
            if (!MerkleProof.verify(merkleProof, offer.merkleRoot, leaf)) {
                revert InvalidProof();
            }
        }

        if (offer.maxRedemptions > 0 && offer.currentRedemptions >= offer.maxRedemptions) {
            revert LimitExceeded("offer redemptions", offer.currentRedemptions, offer.maxRedemptions);
        }

        // SECURITY: Counter overflow protection
        if (_tokenIds >= type(uint256).max - 1) {
            revert CounterOverflow("tokenIds");
        }

        // SECURITY: Complete state changes before external calls
        _tokenIds = _tokenIds + 1;
        uint256 tokenId = _tokenIds;

        offer.redeemedBy[_msgSender()] = true;
        offer.userRedemptions[_msgSender()] = offer.userRedemptions[_msgSender()] + 1;
        offer.currentRedemptions = offer.currentRedemptions + 1;

        _tokenTypes[tokenId] = TokenType.OFFER_COUPON;
        _tokenReferences[tokenId] = offerId;

        // SECURITY: External call last
        _safeMint(_msgSender(), tokenId);

        emit OfferRedeemed(offerId, _msgSender());
    }

    function checkOfferExpiration(uint256 offerId) external {
        Offer storage offer = _offers[offerId];
        if (offer.offerId == 0) {
            revert DoesNotExist("offer");
        }

        if (block.timestamp > offer.validUntil && offer.isActive) {
            offer.isActive = false;
            emit OfferExpired(offerId);
        }
    }

    // ============ ACCESS CONTROL FUNCTIONS ============

    function authorizeBrand(address brand) external onlyOwner {
        _validateAddress(brand, "brand");

        if (_authorizedBrands[brand]) {
            revert AlreadyExists("authorized brand");
        }

        _authorizedBrands[brand] = true;
        emit BrandAuthorized(brand);
    }

    function revokeBrand(address brand) external onlyOwner {
        if (!_authorizedBrands[brand]) {
            revert DoesNotExist("authorized brand");
        }

        _authorizedBrands[brand] = false;
        emit BrandRevoked(brand);
    }

    function authorizeOperator(address operator) external onlyOwner {
        _validateAddress(operator, "operator");

        if (_authorizedOperators[operator]) {
            revert AlreadyExists("authorized operator");
        }

        _authorizedOperators[operator] = true;
        emit OperatorAuthorized(operator);
    }

    function revokeOperator(address operator) external onlyOwner {
        if (!_authorizedOperators[operator]) {
            revert DoesNotExist("authorized operator");
        }

        _authorizedOperators[operator] = false;
        emit OperatorRevoked(operator);
    }

    function activateEmergencyStop() external onlyOwner {
        if (_emergencyStop) {
            revert InvalidState("not active", "already active");
        }
        _emergencyStop = true;
        emit EmergencyStopActivated();
    }

    function deactivateEmergencyStop() external onlyOwner {
        if (!_emergencyStop) {
            revert InvalidState("active", "not active");
        }
        _emergencyStop = false;
        emit EmergencyStopDeactivated();
    }

    // ============ PAUSABLE FUNCTIONS ============

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "2.0.0-secure";
    }
}

contracts/fixcontract/TrataTechOwnership.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TrataTechOwnershipRegistryUpgradeableSecure
 * @dev SECURITY FIXED: Upgradeable and gasless version of Ownership Registry Contract for managing NFT-linked digital deeds and transfer logic
 * @dev FIXES: Storage layout, unbounded loops, input validation, reentrancy protection
 * @author Advanced Developer - Security Enhanced Version
 */
contract TrataTechOwnershipRegistryUpgradeableSecure is
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable,
    ERC2771ContextUpgradeable
{
    using ECDSA for bytes32;
    using Strings for uint256;

    // ============ CONSTANTS (FIXED: Moved before state variables) ============

    uint256 public constant FEE_DENOMINATOR = 10000;
    uint256 public constant MAX_TRANSFER_REQUESTS = 50; // SECURITY: Prevent DoS
    uint256 public constant MAX_QUERY_RESULTS = 100; // SECURITY: Prevent gas limit issues
    uint256 public constant MIN_LOCK_DURATION = 1 hours;
    uint256 public constant MAX_LOCK_DURATION = 365 days;
    uint256 public constant MAX_ADDITIONAL_DATA = 20; // SECURITY: Prevent large loops

    // ============ STRUCTS ============

    struct OwnershipDeed {
        uint256 deedId;
        uint256 passportId;
        address owner;
        uint256 acquisitionDate;
        uint256 acquisitionPrice;
        string acquisitionMethod;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isLocked;
        uint256 lockExpiry;
        address previousOwner;
        uint256 pendingRequestCount; // Track count to avoid loop
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct TransferRequest {
        uint256 requestId;
        uint256 deedId;
        address from;
        address to;
        uint256 requestDate;
        uint256 proposedPrice;
        string transferReason;
        TransferStatus status;
        address requester;
        uint256 expiryDate;
        bool isApproved;
        address approver;
    }

    struct RoyaltyInfo {
        address recipient;
        uint256 percentage; // In basis points (e.g., 500 = 5%)
        bool isActive;
    }

    enum TransferStatus {
        PENDING,
        APPROVED,
        REJECTED,
        EXPIRED,
        CANCELLED
    }

    enum TransferType {
        PRIMARY_SALE,
        SECONDARY_SALE,
        GIFT,
        INHERITANCE,
        LOAN,
        CONSIGNMENT,
        AUCTION,
        CUSTOM
    }

    // ============ STATE VARIABLES (FIXED: Proper ordering) ============

    uint256 private _deedIds;
    uint256 private _requestIds;

    // Transfer settings
    uint256 public transferApprovalPeriod;
    uint256 public maxTransferRequests;

    // Emergency controls
    bool public emergencyStop;

    // Mappings
    mapping(uint256 => OwnershipDeed) public ownershipDeeds;
    mapping(uint256 => TransferRequest) public transferRequests;
    mapping(uint256 => uint256) public passportToDeed;
    mapping(address => uint256[]) public ownerToDeeds;
    mapping(uint256 => RoyaltyInfo) public deedRoyalties;
    mapping(address => bool) public authorizedBrands;
    mapping(address => bool) public authorizedOperators;
    mapping(address => bool) public authorizedTransferAgents;

    // SECURITY FIX: Add mappings to track pending requests per deed for pagination
    mapping(uint256 => uint256[]) public deedToPendingRequests;
    mapping(uint256 => mapping(uint256 => bool)) public requestIndexExists;

    // Reserved for future use (FIXED: Proper gap size after accounting for new variables)
    uint256[41] private __gap;

    // ============ CUSTOM ERRORS (SECURITY: More descriptive error handling) ============

    error InvalidAddress(string param);
    error InvalidDeedId(uint256 deedId);
    error InvalidRequestId(uint256 requestId);
    error DeedNotFound(uint256 deedId);
    error DeedInvalid(uint256 deedId);
    error DeedLocked(uint256 deedId, uint256 lockExpiry);
    error NotDeedOwner(uint256 deedId, address caller);
    error NotAuthorized(string role, address caller);
    error EmergencyStopActive();
    error TooManyRequests(uint256 current, uint256 max);
    error InvalidTimeRange(uint256 start, uint256 end);
    error CounterOverflow(string counter);

    // ============ EVENTS ============

    event OwnershipDeedCreated(
        uint256 indexed deedId,
        uint256 indexed passportId,
        address indexed owner,
        uint256 acquisitionPrice,
        string acquisitionMethod,
        string ipfsCID
    );

    event OwnershipDeedTransferred(
        uint256 indexed deedId,
        address indexed from,
        address indexed to,
        uint256 transferPrice,
        TransferType transferType
    );

    event TransferRequestCreated(
        uint256 indexed requestId,
        uint256 indexed deedId,
        address indexed from,
        address to,
        uint256 proposedPrice,
        TransferStatus status
    );

    event TransferRequestApproved(
        uint256 indexed requestId,
        address indexed approver
    );

    event TransferRequestRejected(
        uint256 indexed requestId,
        string reason,
        address indexed rejector
    );

    event DeedLockedEvent(
        uint256 indexed deedId,
        uint256 lockExpiry,
        address indexed locker
    );

    event DeedUnlocked(
        uint256 indexed deedId,
        address indexed unlocker
    );

    event RoyaltySet(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 percentage
    );

    event RoyaltyPaid(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 amount
    );

    // ============ MODIFIERS (SECURITY: Enhanced input validation) ============

    modifier onlyAuthorizedBrand() {
        if (!authorizedBrands[_msgSender()] && _msgSender() != owner()) {
            revert NotAuthorized("brand", _msgSender());
        }
        _;
    }

    modifier onlyAuthorizedOperator() {
        if (!authorizedOperators[_msgSender()] && _msgSender() != owner()) {
            revert NotAuthorized("operator", _msgSender());
        }
        _;
    }

    modifier onlyAuthorizedTransferAgent() {
        if (!authorizedTransferAgents[_msgSender()] && _msgSender() != owner()) {
            revert NotAuthorized("transfer agent", _msgSender());
        }
        _;
    }

    modifier notEmergencyStopped() {
        if (emergencyStop) {
            revert EmergencyStopActive();
        }
        _;
    }

    modifier validDeed(uint256 deedId) {
        if (ownershipDeeds[deedId].deedId == 0) {
            revert DeedNotFound(deedId);
        }
        if (!ownershipDeeds[deedId].isValid) {
            revert DeedInvalid(deedId);
        }
        _;
    }

    modifier onlyDeedOwner(uint256 deedId) {
        if (ownershipDeeds[deedId].owner != _msgSender()) {
            revert NotDeedOwner(deedId, _msgSender());
        }
        _;
    }

    modifier deedNotLocked(uint256 deedId) {
        if (ownershipDeeds[deedId].isLocked && ownershipDeeds[deedId].lockExpiry >= block.timestamp) {
            revert DeedLocked(deedId, ownershipDeeds[deedId].lockExpiry);
        }
        _;
    }

    modifier validAddress(address addr, string memory param) {
        if (addr == address(0)) {
            revert InvalidAddress(param);
        }
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        if (trustedForwarder == address(0)) {
            revert InvalidAddress("trustedForwarder");
        }
        _disableInitializers();
    }

    function initialize(
        address initialOwner,
        address trustedForwarder
    ) public initializer validAddress(initialOwner, "initialOwner") validAddress(trustedForwarder, "trustedForwarder") {
        __ERC721_init("TrataTech Ownership Deed", "TRATA-DEED");
        __Ownable_init(initialOwner);
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        // ERC2771Context initialization removed - constructor handles this

        _deedIds = 1; // Start from 1
        _requestIds = 1; // Start from 1
        // Fee collection removed - no blockchain payments
        transferApprovalPeriod = 7 days;
        maxTransferRequests = MAX_TRANSFER_REQUESTS;
    }

    // ============ UUPS UPGRADE AUTHORIZATION ============

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ ERC2771 OVERRIDES FOR GASLESS ============

    function _msgSender() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view virtual override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ OWNERSHIP DEED MANAGEMENT (SECURITY: Enhanced validation) ============

    function createOwnershipDeed(
        uint256 passportId,
        address owner,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external
        onlyAuthorizedBrand
        notEmergencyStopped
        nonReentrant
        validAddress(owner, "owner")
    {
        // SECURITY: Enhanced input validation
        if (passportId == 0) revert InvalidDeedId(passportId);
        if (bytes(acquisitionMethod).length == 0) revert InvalidAddress("acquisitionMethod");
        if (bytes(ipfsCID).length == 0) revert InvalidAddress("ipfsCID");
        if (bytes(metadataHash).length == 0) revert InvalidAddress("metadataHash");
        if (passportToDeed[passportId] != 0) revert InvalidDeedId(passportId);
        if (additionalData.length > MAX_ADDITIONAL_DATA) revert TooManyRequests(additionalData.length, MAX_ADDITIONAL_DATA);

        // SECURITY: Counter overflow protection
        if (_deedIds >= type(uint256).max - 1) {
            revert CounterOverflow("deedIds");
        }

        _deedIds = _deedIds + 1;
        uint256 deedId = _deedIds;

        OwnershipDeed storage newDeed = ownershipDeeds[deedId];
        newDeed.deedId = deedId;
        newDeed.passportId = passportId;
        newDeed.owner = owner;
        newDeed.acquisitionDate = block.timestamp;
        newDeed.acquisitionPrice = acquisitionPrice;
        newDeed.acquisitionMethod = acquisitionMethod;
        newDeed.ipfsCID = ipfsCID;
        newDeed.metadataHash = metadataHash;
        newDeed.isValid = true;
        newDeed.isLocked = false;
        newDeed.pendingRequestCount = 0;
        newDeed.lockExpiry = 0;
        newDeed.previousOwner = address(0);

        // Add additional data with bounds checking
        for (uint256 i = 0; i < additionalData.length && i + 1 < additionalData.length; i += 2) {
            string memory key = additionalData[i];
            string memory value = additionalData[i + 1];
            if (bytes(key).length > 0) { // SECURITY: Validate key
                newDeed.additionalData[key] = value;
                newDeed.dataKeys.push(key);
            }
        }

        // Update mappings
        passportToDeed[passportId] = deedId;
        ownerToDeeds[owner].push(deedId);

        // Mint NFT
        _safeMint(owner, deedId);

        emit OwnershipDeedCreated(deedId, passportId, owner, acquisitionPrice, acquisitionMethod, ipfsCID);
    }

    function transferOwnershipDeed(
        uint256 deedId,
        address to,
        uint256 transferPrice,
        TransferType transferType,
        string memory ipfsCID
    ) external
        validDeed(deedId)
        onlyDeedOwner(deedId)
        deedNotLocked(deedId)
        notEmergencyStopped
        nonReentrant
        validAddress(to, "to")
    {
        // SECURITY: Enhanced validation
        if (to == _msgSender()) revert InvalidAddress("cannot transfer to self");
        if (bytes(ipfsCID).length == 0) revert InvalidAddress("ipfsCID");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        address from = deed.owner;

        // Handle royalties if applicable
        if (transferPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (transferPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                // Royalty payment removed - no blockchain payments
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // SECURITY FIX: Complete state changes before external calls
        deed.previousOwner = from;
        deed.owner = to;

        // Update mappings before external calls
        _removeDeedFromOwner(from, deedId);
        ownerToDeeds[to].push(deedId);

        // Transfer NFT (external call last)
        _transfer(from, to, deedId);

        emit OwnershipDeedTransferred(deedId, from, to, transferPrice, transferType);
    }

    function lockDeed(uint256 deedId, uint256 lockDuration) external validDeed(deedId) onlyDeedOwner(deedId) {
        // SECURITY: Enhanced validation
        if (lockDuration < MIN_LOCK_DURATION) revert InvalidTimeRange(lockDuration, MIN_LOCK_DURATION);
        if (lockDuration > MAX_LOCK_DURATION) revert InvalidTimeRange(lockDuration, MAX_LOCK_DURATION);

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        deed.isLocked = true;
        deed.lockExpiry = block.timestamp + lockDuration;

        emit DeedLockedEvent(deedId, deed.lockExpiry, _msgSender());
    }

    function unlockDeed(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        if (!deed.isLocked) revert InvalidDeedId(deedId);
        if (deed.lockExpiry >= block.timestamp) revert DeedLocked(deedId, deed.lockExpiry);

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, _msgSender());
    }

    function forceUnlockDeed(uint256 deedId) external onlyAuthorizedOperator validDeed(deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        if (!deed.isLocked) revert InvalidDeedId(deedId);

        deed.isLocked = false;
        deed.lockExpiry = 0;

        emit DeedUnlocked(deedId, _msgSender());
    }

    // ============ TRANSFER REQUEST MANAGEMENT (SECURITY: Enhanced validation) ============

    function createTransferRequest(
        uint256 deedId,
        address to,
        uint256 proposedPrice,
        string memory transferReason
    ) external
        validDeed(deedId)
        deedNotLocked(deedId)
        notEmergencyStopped
        validAddress(to, "to")
    {
        // SECURITY: Enhanced validation
        if (to == _msgSender()) revert InvalidAddress("cannot transfer to self");
        if (bytes(transferReason).length == 0) revert InvalidAddress("transferReason");

        // Check if there are too many pending requests using counter
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        if (deed.pendingRequestCount >= maxTransferRequests) {
            revert TooManyRequests(deed.pendingRequestCount, maxTransferRequests);
        }

        // SECURITY: Counter overflow protection
        if (_requestIds >= type(uint256).max - 1) {
            revert CounterOverflow("requestIds");
        }

        _requestIds = _requestIds + 1;
        uint256 requestId = _requestIds;

        TransferRequest storage newRequest = transferRequests[requestId];
        newRequest.requestId = requestId;
        newRequest.deedId = deedId;
        newRequest.from = ownershipDeeds[deedId].owner;
        newRequest.to = to;
        newRequest.requestDate = block.timestamp;
        newRequest.proposedPrice = proposedPrice;
        newRequest.transferReason = transferReason;
        newRequest.status = TransferStatus.PENDING;
        newRequest.requester = _msgSender();
        newRequest.expiryDate = block.timestamp + transferApprovalPeriod;
        newRequest.isApproved = false;
        newRequest.approver = address(0);

        // Increment pending request counter and add to tracking
        deed.pendingRequestCount++;
        deedToPendingRequests[deedId].push(requestId);
        requestIndexExists[deedId][requestId] = true;

        emit TransferRequestCreated(requestId, deedId, _msgSender(), to, proposedPrice, TransferStatus.PENDING);
    }

    function approveTransferRequest(uint256 requestId) external validDeed(transferRequests[requestId].deedId) {
        TransferRequest storage request = transferRequests[requestId];
        if (request.requestId == 0) revert InvalidRequestId(requestId);
        if (request.status != TransferStatus.PENDING) revert InvalidRequestId(requestId);
        if (request.expiryDate <= block.timestamp) revert InvalidTimeRange(block.timestamp, request.expiryDate);
        if (request.from != _msgSender()) revert NotDeedOwner(request.deedId, _msgSender());

        request.status = TransferStatus.APPROVED;
        request.isApproved = true;
        request.approver = _msgSender();

        // Decrement pending request counter and remove from tracking
        OwnershipDeed storage deed = ownershipDeeds[request.deedId];
        deed.pendingRequestCount--;
        _removePendingRequest(request.deedId, requestId);

        emit TransferRequestApproved(requestId, _msgSender());
    }

    function rejectTransferRequest(uint256 requestId, string memory reason) external validDeed(transferRequests[requestId].deedId) {
        // SECURITY: Enhanced validation
        if (bytes(reason).length == 0) revert InvalidAddress("reason");

        TransferRequest storage request = transferRequests[requestId];
        if (request.requestId == 0) revert InvalidRequestId(requestId);
        if (request.status != TransferStatus.PENDING) revert InvalidRequestId(requestId);
        if (request.from != _msgSender()) revert NotDeedOwner(request.deedId, _msgSender());

        request.status = TransferStatus.REJECTED;

        // Decrement pending request counter and remove from tracking
        OwnershipDeed storage deed = ownershipDeeds[request.deedId];
        deed.pendingRequestCount--;
        _removePendingRequest(request.deedId, requestId);

        emit TransferRequestRejected(requestId, reason, _msgSender());
    }

    function executeTransferRequest(
        uint256 requestId,
        string memory ipfsCID
    ) external validDeed(transferRequests[requestId].deedId) notEmergencyStopped nonReentrant {
        // SECURITY: Enhanced validation
        if (bytes(ipfsCID).length == 0) revert InvalidAddress("ipfsCID");

        TransferRequest storage request = transferRequests[requestId];
        if (request.requestId == 0) revert InvalidRequestId(requestId);
        if (request.status != TransferStatus.APPROVED) revert InvalidRequestId(requestId);
        if (request.expiryDate <= block.timestamp) revert InvalidTimeRange(block.timestamp, request.expiryDate);
        if (request.requester != _msgSender()) revert NotAuthorized("requester", _msgSender());

        uint256 deedId = request.deedId;
        OwnershipDeed storage deed = ownershipDeeds[deedId];

        // Handle royalties if applicable
        if (request.proposedPrice > 0 && deedRoyalties[deedId].isActive) {
            uint256 royaltyAmount = (request.proposedPrice * deedRoyalties[deedId].percentage) / FEE_DENOMINATOR;
            if (royaltyAmount > 0) {
                // Royalty payment removed - no blockchain payments
                emit RoyaltyPaid(deedId, deedRoyalties[deedId].recipient, royaltyAmount);
            }
        }

        // SECURITY FIX: Complete state changes before external calls
        deed.previousOwner = request.from;
        deed.owner = request.to;

        // Update mappings before external calls
        _removeDeedFromOwner(request.from, deedId);
        ownerToDeeds[request.to].push(deedId);

        // Transfer NFT (external call last)
        _transfer(request.from, request.to, deedId);

        // Mark request as completed
        request.status = TransferStatus.APPROVED;

        emit OwnershipDeedTransferred(deedId, request.from, request.to, request.proposedPrice, TransferType.SECONDARY_SALE);
    }

    // ============ ROYALTY MANAGEMENT (SECURITY: Enhanced validation) ============

    function setRoyalty(
        uint256 deedId,
        address recipient,
        uint256 percentage
    ) external validDeed(deedId) onlyDeedOwner(deedId) validAddress(recipient, "recipient") {
        // SECURITY: Enhanced validation - max 10%
        if (percentage > 1000) revert InvalidTimeRange(percentage, 1000);

        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        royalty.recipient = recipient;
        royalty.percentage = percentage;
        royalty.isActive = true;

        emit RoyaltySet(deedId, recipient, percentage);
    }

    function disableRoyalty(uint256 deedId) external validDeed(deedId) onlyDeedOwner(deedId) {
        deedRoyalties[deedId].isActive = false;
    }

    // ============ ADMIN FUNCTIONS (SECURITY: Enhanced validation) ============

    function authorizeBrand(address brand) external onlyOwner validAddress(brand, "brand") {
        authorizedBrands[brand] = true;
    }

    function authorizeOperator(address operator) external onlyOwner validAddress(operator, "operator") {
        authorizedOperators[operator] = true;
    }

    function authorizeTransferAgent(address transferAgent) external onlyOwner validAddress(transferAgent, "transferAgent") {
        authorizedTransferAgents[transferAgent] = true;
    }

    function revokeAuthorization(address target) external onlyOwner validAddress(target, "target") {
        authorizedBrands[target] = false;
        authorizedOperators[target] = false;
        authorizedTransferAgents[target] = false;
    }

    function setSettings(
        uint256 newApprovalPeriod,
        uint256 newMaxRequests
    ) external onlyOwner {
        // SECURITY: Validate settings bounds
        if (newMaxRequests > MAX_TRANSFER_REQUESTS) revert TooManyRequests(newMaxRequests, MAX_TRANSFER_REQUESTS);

        transferApprovalPeriod = newApprovalPeriod;
        maxTransferRequests = newMaxRequests;
    }

    function activateEmergencyStop() external onlyOwner {
        emergencyStop = true;
    }

    function deactivateEmergencyStop() external onlyOwner {
        emergencyStop = false;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ VIEW FUNCTIONS (SECURITY: Pagination and bounds checking) ============

    function getOwnershipDeedDetails(uint256 deedId) external view returns (
        uint256 passportId,
        address owner,
        uint256 acquisitionDate,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        bool isValid,
        bool isLocked,
        uint256 lockExpiry,
        address previousOwner
    ) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        return (
            deed.passportId,
            deed.owner,
            deed.acquisitionDate,
            deed.acquisitionPrice,
            deed.acquisitionMethod,
            deed.ipfsCID,
            deed.metadataHash,
            deed.isValid,
            deed.isLocked,
            deed.lockExpiry,
            deed.previousOwner
        );
    }

    function getDeedByPassportId(uint256 passportId) external view returns (uint256) {
        return passportToDeed[passportId];
    }

    function getDeedsByOwner(address owner) external view returns (uint256[] memory) {
        return ownerToDeeds[owner];
    }

    function getTransferRequestDetails(uint256 requestId) external view returns (
        uint256 deedId,
        address from,
        address to,
        uint256 requestDate,
        uint256 proposedPrice,
        string memory transferReason,
        TransferStatus status,
        address requester,
        uint256 expiryDate,
        bool isApproved,
        address approver
    ) {
        TransferRequest storage request = transferRequests[requestId];
        return (
            request.deedId,
            request.from,
            request.to,
            request.requestDate,
            request.proposedPrice,
            request.transferReason,
            request.status,
            request.requester,
            request.expiryDate,
            request.isApproved,
            request.approver
        );
    }

    function getRoyaltyInfo(uint256 deedId) external view returns (
        address recipient,
        uint256 percentage,
        bool isActive
    ) {
        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        return (
            royalty.recipient,
            royalty.percentage,
            royalty.isActive
        );
    }

    function getDeedData(uint256 deedId, string memory key) external view returns (string memory) {
        return ownershipDeeds[deedId].additionalData[key];
    }

    function getDeedDataKeys(uint256 deedId) external view returns (string[] memory) {
        return ownershipDeeds[deedId].dataKeys;
    }

    // SECURITY FIX: Paginated version to prevent gas limit issues
    function getPendingTransferRequests(
        uint256 deedId,
        uint256 offset,
        uint256 limit
    ) external view returns (uint256[] memory) {
        uint256[] storage pendingRequests = deedToPendingRequests[deedId];

        // SECURITY: Limit results to prevent gas issues
        if (limit > MAX_QUERY_RESULTS) {
            limit = MAX_QUERY_RESULTS;
        }

        if (offset >= pendingRequests.length) {
            return new uint256[](0);
        }

        uint256 end = offset + limit;
        if (end > pendingRequests.length) {
            end = pendingRequests.length;
        }

        uint256[] memory result = new uint256[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = pendingRequests[i];
        }

        return result;
    }

    // BACKWARD COMPATIBILITY: Keep original function but with safety limits
    function getPendingTransferRequests(uint256 deedId) external view returns (uint256[] memory) {
        return this.getPendingTransferRequests(deedId, 0, MAX_QUERY_RESULTS);
    }

    function getTotalDeeds() external view returns (uint256) {
        return _deedIds - 1;
    }

    function getTotalTransferRequests() external view returns (uint256) {
        return _requestIds - 1;
    }

    function getPendingRequestCount(uint256 deedId) external view returns (uint256) {
        return deedToPendingRequests[deedId].length;
    }

    // ============ INTERNAL FUNCTIONS (SECURITY: Enhanced safety) ============

    function _removeDeedFromOwner(address owner, uint256 deedId) internal {
        uint256[] storage deeds = ownerToDeeds[owner];
        for (uint256 i = 0; i < deeds.length; i++) {
            if (deeds[i] == deedId) {
                deeds[i] = deeds[deeds.length - 1];
                deeds.pop();
                break;
            }
        }
    }

    function _removePendingRequest(uint256 deedId, uint256 requestId) internal {
        if (!requestIndexExists[deedId][requestId]) {
            return; // Already removed
        }

        uint256[] storage requests = deedToPendingRequests[deedId];
        for (uint256 i = 0; i < requests.length; i++) {
            if (requests[i] == requestId) {
                requests[i] = requests[requests.length - 1];
                requests.pop();
                requestIndexExists[deedId][requestId] = false;
                break;
            }
        }
    }

    // ============ VERSION FUNCTION ============

    function version() external pure returns (string memory) {
        return "1.1.0-secure";
    }
}

